259	  const arp = [C4, E4, G4, C5, G4, E4, A4, C5, E4, A4, C5, E4, F4, A4, C5, F4];
260	  arp.forEach((f, i) => {
261	    addTone(buf, sr, { start: i * 0.2, dur: 0.18, freq: f, type: 'triangle', gain: 0.11, decayPow: 2 });
