56	// ── Oscillators ──────────────────────────────────────────────────────────────
57	type WaveType = 'sine' | 'square' | 'triangle' | 'saw' | 'noise';
58	
59	function waveSample(type: WaveType, phase: number): number {
60	  const p = phase - Math.floor(phase); // wrap to [0,1)
61	  switch (type) {
62	    case 'sine':
63	      return Math.sin(p * Math.PI * 2);
64	    case 'square':
65	      return p < 0.5 ? 1 : -1;
66	    case 'triangle':
67	      return 4 * Math.abs(p - 0.5) - 1;
68	    case 'saw':
69	      return 2 * p - 1;
70	    case 'noise':
71	      return Math.random() * 2 - 1;
72	    default:
73	      return 0;
74	  }
75	}
