300	interface AudioDef {
301	  readonly key: string;
302	  readonly sr: number;
303	  readonly make: () => Float32Array;
304	}
305	
306	const AUDIO_DEFS: readonly AudioDef[] = [
307	  { key: Sfx.jump, sr: SFX_SR, make: makeJump },
308	  { key: Sfx.hit, sr: SFX_SR, make: makeHit },
309	  { key: Sfx.tablet, sr: SFX_SR, make: makeTablet },
310	  { key: Sfx.armor, sr: SFX_SR, make: makeArmor },
311	  { key: Sfx.victory, sr: SFX_SR, make: makeVictory },
312	  { key: Sfx.defeat, sr: SFX_SR, make: makeDefeat },
313	  { key: Sfx.ui, sr: SFX_SR, make: makeUi },
314	  { key: Music.menu, sr: MUSIC_SR, make: makeMenuMusic },
315	  { key: Music.game, sr: MUSIC_SR, make: makeGameMusic },
316	];
