318	// Generate the blob URLs once (idempotent across scene reloads).
319	let urlCache: Map<string, string> | undefined;
320	function audioUrls(): Map<string, string> {
321	  if (!urlCache) {
322	    urlCache = new Map();
323	    for (const def of AUDIO_DEFS) urlCache.set(def.key, wavUrl(def.make(), def.sr));
324	  }
325	  return urlCache;
326	}
