343	// Single looping music track shared across scenes (the sound manager is global).
344	let currentMusic: Phaser.Sound.BaseSound | undefined;
345	let currentMusicKey: MusicKey | undefined;
346	
347	export function playMusic(scene: Phaser.Scene, key: MusicKey): void {
348	  if (currentMusicKey === key && currentMusic && (currentMusic.isPlaying || currentMusic.isPaused)) {
349	    return; // already the active track — don't restart or stack
350	  }
351	  stopMusic();
352	  const music = scene.sound.add(key, { loop: true, volume: AUDIO.musicVolume });
353	  music.play();
354	  currentMusic = music;
355	  currentMusicKey = key;
356	}
