33	 * instances via `group.get()` and returns them with `recycle()`. No per-spawn GC.
34	 *
35	 * Spawning is DISTANCE-scheduled: because entities move left at exactly the world
36	 * speed and the distance metric advances at the same rate, scheduling a spawn every
37	 * `S` world-units yields a clean `S` px on-screen gap regardless of the speed ramp.
38	 * That keeps hazard spacing FAIR and jump-clearable (§3.2) — hazards sit on the
39	 * ground; tablets/armor hover so the same jump both clears a hazard and collects.
40	 */
41	export class Spawner {
42	  readonly tickPool: Phaser.Physics.Arcade.Group;
43	  readonly bushPool: Phaser.Physics.Arcade.Group;
44	  readonly puddlePool: Phaser.Physics.Arcade.Group;
45	  readonly tabletPool: Phaser.Physics.Arcade.Group;
46	  readonly armorPool: Phaser.Physics.Arcade.Group;
47	
48	  private readonly allPools: Phaser.Physics.Arcade.Group[];
49	  private readonly hazardTable: HazardChoice[];
50	  private readonly hazardWeightTotal: number;
51	
52	  private nextHazardDistance = HAZARD_SPACING_START;
53	  private nextTabletDistance = TABLET_SPACING_START;
54	  private readonly armorQueue: number[] = [];
55	  private spawningEnabled = true;
